const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.geometry.Point([-121.37, 47.36]).buffer(5000); // Keechelus Lake, WA with a 5km buffer
  const start_date_1 = '2024-07-01';
  const end_date_1 = '2024-07-31';
  const start_date_2 = '2025-07-01';
  const end_date_2 = '2025-07-31';

  // 2. Data Acquisition & Pre-processing
  // Use JRC Global Surface Water dataset for yearly water history.
  // This dataset is pre-computed and reliable for historical analysis.
  const dataset = ee.ImageCollection('JRC/GSW1_4/YearlyHistory');

  // Function to calculate water area for a given year
  const calculateWaterArea = (year) => {
    const imageCollection = dataset.filter(ee.Filter.calendarRange(year, year, 'year'));

    // Check if data exists for the year
    const imageCount = imageCollection.size().getInfo();
    if (imageCount === 0) {
      return { 'count': 0, 'area': null };
    }

    const image = imageCollection.first();
    // Select the 'waterClass' band. Values are: 1 (not water), 2 (seasonal), 3 (permanent).
    // We consider both seasonal and permanent water as water.
    const waterImage = image.select('waterClass').gte(2);

    // Calculate the area of water pixels
    const waterArea = waterImage.multiply(ee.Image.pixelArea()).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: 30, // Native resolution of JRC data
      maxPixels: 1e9
    });

    return { 'count': imageCount, 'area': waterArea.get('waterClass') };
  };

  // 3. Calculation
  const water2024 = calculateWaterArea(2024);
  const water2025 = calculateWaterArea(2025);

  // 4. Validation & Final Answer
  console.log(`Images found for 2024: ${water2024.count}`);
  console.log(`Images found for 2025: ${water2025.count}`);

  // The JRC dataset, like most satellite data, is not available for future dates.
  // This check will confirm no images are found.
  if (water2024.count === 0 || water2025.count === 0) {
    console.log('Evidence: Satellite data for future dates (2024, 2025) is not available.');
    console.log('C1: Empty Collection');
  } else {
    // This block is unlikely to be reached due to future dates but included for logical completeness.
    const area2024 = ee.Number(water2024.area).getInfo();
    const area2025 = ee.Number(water2025.area).getInfo();

    if (area2024 === null || area2025 === null) {
      console.log('Evidence: Could not calculate water area for one or both periods.');
      console.log('C3: Calculation Failure');
    } else {
      console.log(`2024 Water Area (sq meters): ${area2024.toFixed(2)}`);
      console.log(`2025 Water Area (sq meters): ${area2025.toFixed(2)}`);
      if (area2025 < area2024) {
        console.log('A');
      } else {
        console.log('B');
      }
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log('D');
